-- 393: SX コスト試算を 260913 二段階版へ組み替える（2026-09-13 まさ確定）
--
-- 先に 392 を適用すること。260820版（ちこ作成）の明細を土台に、次を行う。
--   - 中央培養の明細を 円/m³ → 円/kg-DCW・年額固定へ換算し、年間生産能力の前提を足す
--   - 色素分解と金属回収で前提・明細を分ける。金属の取り込み効率を株ごとに置き直す
--   - 人件費を総コストへ入れる。巡回サービス・閉鎖系の追加費用（強化株のみ）・色素用の後処理・色素の濃さを足す
-- 生成: えいみ 2026-09-13（SXセッション）。DB から取り出した現行データを変換して書き出した。
begin;
update project_cost_models set case_kind = 'multi', case_label = '色素分解・金属回収', version_label = '260913 二段階版', summary_md = 'SXの排液処理を、**菌体の製造原価**と**用途別の処理原価**の二段階で試算する。

**第1段 菌体の製造原価** — 株（強化株／自然株）ごとに、中央培養拠点で乾燥菌体1kgをつくる原価を出す。同じ株なら用途では変わらない。強化株は閉鎖系の追加費用が乗る。

**第2段 用途別の処理原価** — 第1段の原価を一定として、色素分解と金属回収のそれぞれで排水1m³あたりの総コストを出す。用途で変わるのは、必要な菌体の量（対象物質の濃度 ÷ 取り込み効率 ÷ 菌体使用回数）と、使用済み菌体の後処理。

画面上部のスイッチで株を切り替える。切り替えは保存しない（見るだけ）。

ちこ作成の260820版の明細を土台に、2026-09-13に二段階へ組み替えた。人件費・巡回サービス・閉鎖系の追加費用・色素用の後処理・色素の濃さを追加し、いずれも確度つきで置いている。', system_scope_md = '**対象** — 工場排液を、生きたシアノバクテリア（藍藻）で処理する。用途は色素分解と金属回収の2つを並べる。

**規模** — 顧客工場1拠点あたり 100 m³/日 × 300 日/年 ＝ 30,000 m³/年。1バッチ100 m³、反応時間（HRT）4時間のバッチ運転。

**第1段：菌体は中央培養拠点で作る** — 各現場では培養しない。乾燥菌体1kgあたりの原価は、「(培養設備の償却年額 ＋ 年ごとの固定費) ÷ 年間生産能力 ＋ 菌体量に比例する費用」で出す。年間生産能力いっぱいで割るので、稼働が低いと実際の1kgあたり原価は上がる。

**第2段：方式は2つを並べて比較する**
- **A：循環カートリッジ方式** — 菌体をカートリッジ内の保持モジュールに留め、排液を循環させて接触させる。モジュールは耐用バッチ数ごとに交換する。
- **B：直接投入方式** — 菌体を槽へ直接投入して撹拌し、反応後に UF/MF 膜で菌体を分離回収する。膜は約3年で交換する。

**槽は既設／新設の2通り** — 顧客の既存調整タンクを流用できれば0円。新設ならコンクリート地下タンク100 m³で1,800万円（10年償却）。方式×槽で、用途ごとに4シナリオになる。

**設備は独立プラント新設ではなく増分アドオン** — 顧客の既存調整タンク・排水ライン・ユーティリティ・主処理設備を使い、密閉接触・循環、菌体捕捉、回収サービスを足す（2026-07-23 確定）。

**収益モデル** — 処理費のみ。売価500円/m³。回収物（金属など）の売却収入はまだモデルに入れていない。

**人件費と巡回サービス** — 総コストに入れる（2026-09-13 まさ指示）。人件費は中島先生の試算にある手動運用の作業時間で置き、人件費を除いた値も併記する。菌体の搬入・搬出と、モジュール・膜の交換作業は巡回サービスとして別に積む。', source_note = '原典: Google Sheets SX_コスト試算_260820 (ちこ)。中島先生の設備・運用想定を反映した版。 2026-09-13 に二段階版へ組み替え（migration 393）。', updated_at = now() where cost_model_id = 'cm_p21_260820';
update project_cost_assumptions set code = null, group_label = '人件費', label = '1バッチあたり作業時間（A:循環）', value = 5.75, value_text = null, unit = 'h', confidence = 'A', source_kind = '先生回答', owner = '中島先生', is_key = true, role_key = 'batch_hours_circulation', note = '出所：中島試算シート100m³ケース①循環。手動運用のときの時間。二段階版ではこの時間で人件費を総コストへ入れる。無人運転で何時間まで減るかは未確認（ダイキアクシスへ確認中）。', visibility = 'amd_internal', sort_order = 160, strain = null, application = null, updated_at = now() where cost_assumption_id = 'ca_batch_hours_circulation';
update project_cost_assumptions set code = null, group_label = '人件費', label = '1バッチあたり作業時間（B:投入）', value = 7.5, value_text = null, unit = 'h', confidence = 'A', source_kind = '先生回答', owner = '中島先生', is_key = true, role_key = 'batch_hours_injection', note = '出所：中島試算シート100m³ケース②投入。手動運用のときの時間。二段階版ではこの時間で人件費を総コストへ入れる。無人運転で何時間まで減るかは未確認（ダイキアクシスへ確認中）。', visibility = 'amd_internal', sort_order = 200, strain = null, application = null, updated_at = now() where cost_assumption_id = 'ca_batch_hours_injection';
update project_cost_assumptions set code = null, group_label = '共通前提', label = '人件費単価', value = 4000, value_text = null, unit = '円/h', confidence = 'B', source_kind = '仮置き', owner = 'AMD', is_key = false, role_key = 'labor_rate', note = '現場の運転人件費と、巡回サービス（搬入・搬出・交換作業）の両方に使う。', visibility = 'amd_internal', sort_order = 50, strain = null, application = null, updated_at = now() where cost_assumption_id = 'ca_labor_rate';
update project_cost_assumptions set code = null, group_label = '対象物質', label = '菌体使用回数（色素分解）', value = 1, value_text = null, unit = '回', confidence = 'H', source_kind = '要検証', owner = '杉浦先生', is_key = true, role_key = 'reuse_count', note = '★最大の感度。1＝再利用せず毎回新品。技術的事実ではない保守的仮定。まさの記憶では色素分解なら数十回使い回せる可能性があるが未確認（2026-08-23時点でうろ覚えと明言）。二段階版では菌体原価を1kgあたりで持つので、使用回数を上げると菌体費がそのまま回数分下がる。杉浦先生へ確認中。', visibility = 'amd_internal', sort_order = 130, strain = null, application = 'dye', updated_at = now() where cost_assumption_id = 'ca_reuse_count';
update project_cost_assumptions set code = null, group_label = '中央培養', label = '（旧版）供給先数（中央培養の按分先）', value = 1, value_text = null, unit = '拠点', confidence = 'C', source_kind = '仮置き', owner = 'AMD', is_key = false, role_key = null, note = '二段階版では使わない。菌体の製造原価を「年間生産能力」で割って1kgあたりにしたため、供給先数で割る必要がなくなった。旧版との対応のために残している。', visibility = 'amd_internal', sort_order = 140, strain = null, application = null, updated_at = now() where cost_assumption_id = 'ca_supply_sites';
update project_cost_assumptions set code = null, group_label = '対象物質', label = '対象物質の濃度（金属）', value = 50, value_text = null, unit = 'ppm', confidence = 'A', source_kind = '仮置き', owner = '杉浦先生', is_key = true, role_key = 'target_concentration', note = '★V-401。金属回収ケースの対象金属濃度。260820版から据え置き。色素分解ケースは別行で持つ。', visibility = 'amd_internal', sort_order = 80, strain = null, application = 'metal', updated_at = now() where cost_assumption_id = 'ca_target_concentration';
update project_cost_assumptions set code = null, group_label = '対象物質', label = '取り込み効率α（金属・自然株）', value = 0.042, value_text = null, unit = 'g/g菌体', confidence = 'H', source_kind = '推定', owner = '杉浦先生', is_key = true, role_key = 'uptake_alpha', note = '★V-402。9/2定例の単回試験で、同じ菌体濃度（OD5）の野生型は50ppm中40ppmを取り込み、強化株1は50ppmを全量取り込んで鉄量が乾燥菌体重量比5.3%だった。菌体量が同じと仮定し 5.3% × 40/50 ≒ 4.2% と置いた。260820版の0.05は出所が確認できないため置き換えた。', visibility = 'amd_internal', sort_order = 90, strain = 'wild', application = 'metal', updated_at = now() where cost_assumption_id = 'ca_uptake_alpha';
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_culture_capacity', 'cm_p21_260820', null, '第1段 菌体の製造原価', '中央培養拠点の年間生産能力', 33333, null, 'kg-DCW/年', 'H', '推定', '杉浦先生', true, 'culture_capacity_kg_year', '旧版は「必要な菌体量＝生産量」と暗黙に置いていた（1拠点・使い捨て・50ppm・α0.05で33,333kg/年）。その値を引き継いだ仮置き。培養液1Lあたりの1日の増殖量と培養容積の実測が入るまで確定しない。生産能力いっぱいで割るので、実際の稼働が低いと1kgあたり原価は上がる。', 'amd_internal', 300, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_biomass_override', 'cm_p21_260820', null, '第1段 菌体の製造原価', '菌体の製造原価（上書き）', null, null, '円/kg-DCW', 'H', '仮置き', null, true, 'biomass_cost_per_kg_override', '空欄なら第1段の明細から計算する。値を入れるとその原価で第2段を計算する。閉鎖型の商用相場（約390〜770円/kg）を入れると、菌体原価が相場並みのときの成否が見られる。', 'amd_internal', 310, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_target_concentration_dye', 'cm_p21_260820', null, '対象物質', '対象物質の濃度（色素）', 50, null, 'mg/L', 'H', '仮置き', 'AMD（内部）', true, 'target_concentration', '染色排水の色素濃度は文献上 10〜250 mg/L（多くは10〜50）。その中央の50で置いた。SXが実際に狙う排液の色の濃さは未測定。食品系排液の色は単一の色素濃度ではなく色度で測るため、そのまま当てはめられない。', 'amd_internal', 85, null, 'dye');
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_uptake_alpha_dye', 'cm_p21_260820', null, '対象物質', '取り込み効率α（色素）', 0.05, null, 'g/g菌体', 'H', '仮置き', '杉浦先生', true, 'uptake_alpha', '色素1gを処理するのに菌体が何g要るかの逆数。SXでは未測定。金属と同じ0.05で仮置きした。シアノ系菌体の色素吸着量は、理想条件での上限で約0.28 g/gという報告がある。分解で消える場合は「菌体1gが寿命までに処理できる量」として読む。菌体使用回数と掛け合わせて効く。', 'amd_internal', 95, null, 'dye');
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_uptake_alpha_metal_enhanced', 'cm_p21_260820', null, '対象物質', '取り込み効率α（金属・強化株）', 0.053, null, 'g/g菌体', 'H', '実測', '杉浦先生', true, 'uptake_alpha', '9/2定例の単回試験で、強化株1（OD5）が鉄模擬排液50ppmを24時間で全量取り込み、鉄量が乾燥菌体重量比5.3%。上限に届いていないので、実際の取り込み効率はこれ以上。反復試験と上限探索が技術検証に登録済み。', 'amd_internal', 92, 'enhanced', 'metal');
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_reuse_count_metal', 'cm_p21_260820', null, '対象物質', '菌体使用回数（金属回収）', 1, null, '回', 'A', '推定', null, false, 'reuse_count', '現行の工程は酸で菌体ごと溶かして金属を回収するため1回で使い切る。酸で金属だけを外して菌体を再利用できることが実証されたら変える。', 'amd_internal', 135, null, 'metal');
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_patrol_travel_hours', 'cm_p21_260820', null, '巡回サービス', '1回あたりの移動時間（往復）', 2.0, null, 'h', 'H', '仮置き', 'ダイキアクシス', false, 'patrol_travel_hours', '中央培養拠点から顧客工場までの往復。拠点の立地が決まるまで仮置き。', 'amd_internal', 400, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_patrol_work_hours', 'cm_p21_260820', null, '巡回サービス', '1回あたりの搬入・搬出作業', 1.0, null, 'h', 'H', '仮置き', 'ダイキアクシス', false, 'patrol_work_hours', '菌体の搬入と使用済み菌体の搬出を同じ訪問でまとめる前提。', 'amd_internal', 410, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_patrol_vehicle_cost', 'cm_p21_260820', null, '巡回サービス', '1回あたりの車両費', 5000, null, '円/回', 'H', '仮置き', 'ダイキアクシス', false, 'patrol_vehicle_cost', '燃料・車両償却・高速代の目安。', 'amd_internal', 420, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_patrol_batches_per_delivery', 'cm_p21_260820', null, '巡回サービス', '1回の搬入でまかなうバッチ数', 5, null, '回', 'H', '仮置き', 'ダイキアクシス', false, 'patrol_batches_per_delivery', '菌体を現場で何日保管できるかが分かるまで、週1回（5バッチ分）で置く。菌体使用回数がこれより多いときは、使用回数ごとに1回訪問する。', 'amd_internal', 430, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_patrol_module_work_hours', 'cm_p21_260820', null, '巡回サービス', 'モジュール交換1回の作業時間（A:循環）', 4.0, null, 'h', 'H', '仮置き', 'ダイキアクシス', false, 'patrol_module_work_hours', '移動は搬入の訪問に合わせる前提で、作業時間だけを積む。', 'amd_internal', 440, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_patrol_membrane_work_hours', 'cm_p21_260820', null, '巡回サービス', '膜交換1回の作業時間（B:投入）', 8.0, null, 'h', 'H', '仮置き', 'ダイキアクシス', false, 'patrol_membrane_work_hours', '移動は搬入の訪問に合わせる前提で、作業時間だけを積む。', 'amd_internal', 450, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_spent_wet_factor', 'cm_p21_260820', null, '使用済み菌体の処分', '脱水後の湿重量倍率', 5.0, null, 'kg湿/kg-DCW', 'H', '推定', 'ダイキアクシス', false, 'spent_wet_factor', '含水率80%の脱水汚泥として出す想定（乾燥菌体1kg → 湿重量5kg）。脱水の程度で大きく変わる。', 'amd_internal', 500, null, 'dye');
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('ca2_sludge_disposal_price', 'cm_p21_260820', null, '使用済み菌体の処分', '汚泥の処分単価（収集運搬込み）', 35, null, '円/kg湿', 'B', '資料記載', 'ダイキアクシス', false, 'sludge_disposal_price', '産業廃棄物（汚泥）の処理料金相場 25〜50円/kg の中央。色素を含む菌体の廃棄物区分は未確認。', 'amd_internal', 510, null, 'dye');
update project_cost_items set scenario = '循環', cost_type = 'CAPEX', group_label = '反応・回収設備', mid_label = '分析装置（ポータブル吸光光度計等。金属・色の両方で使う）', leaf_label = '計装', basis = '初期投資配賦', quantity = 1, quantity_unit = '式', unit_price = 1400000, unit_price_unit = '円/式', price_rule = null, annual_factor = 1, useful_life_years = 10, is_breakdown = false, confidence = 'C', source_kind = '先生回答', owner = '中島先生', note = null, visibility = 'amd_internal', sort_order = 350, strain = null, application = null, updated_at = now() where cost_item_id = 'ci_260820_077';
