update project_cost_items set scenario = '投入', cost_type = 'OPEX', group_label = 'リアクター/分離回収/全体共通', mid_label = '反応', leaf_label = '菌体性能低下による交換・再生分', basis = '毎kg菌体比例', quantity = 1, quantity_unit = 'kg-DCW', unit_price = 4.5, unit_price_unit = '円/kg-DCW', price_rule = null, annual_factor = 1, useful_life_years = null, is_breakdown = false, confidence = 'C', source_kind = '仮置き', owner = 'AMD', note = '菌体の金属吸収能力が落ちた分の交換・再生費用。名称を「性能低下見合い追加投入」から明確化。現行式は性能低下率を単純に追加投入する暫定計算。菌体の再生可否・再利用回数・再生コストが未確定のため、この式は暫定扱い。確定後に組み直す。 二段階版で 円/m³ → 円/kg-DCW へ換算した（旧版の基準菌体量 1.111 kg-DCW/m³ で割った値）。', visibility = 'amd_internal', sort_order = 1190, strain = null, application = null, updated_at = now() where cost_item_id = 'ci_260820_161';
