insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application) values ('ci2_patrol_delivery', 'cm_p21_260820', '共通', 'OPEX', '巡回サービス', '菌体の搬入・使用済み菌体の搬出', '訪問回数 ×（移動と作業の時間 × 人件費単価 ＋ 車両費）', 'バッチ連動', 1, null, 0, '円/年', 'patrol', 1, null, false, 'H', '仮置き', 'ダイキアクシス', '訪問回数 = 年間バッチ数 ÷ 大きい方（菌体使用回数, 1回の搬入でまかなうバッチ数）。無人運転でも菌体の搬入・搬出は誰かがやるため、SX側の巡回サービス原価として積む。', 'amd_internal', 1200, null, null);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application) values ('ci2_patrol_module', 'cm_p21_260820', '循環', 'OPEX', '巡回サービス', '菌体保持モジュールの交換作業', '交換回数 × 作業時間 × 人件費単価', 'バッチ連動', 1, null, 0, '円/年', 'patrol_module', 1, null, false, 'H', '仮置き', 'ダイキアクシス', '交換回数 = 年間バッチ数 ÷ モジュール耐用バッチ数。部品代は「菌体保持モジュール交換費」に別計上。', 'amd_internal', 1210, null, null);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application) values ('ci2_patrol_membrane', 'cm_p21_260820', '投入', 'OPEX', '巡回サービス', '膜モジュールの交換作業', '交換回数 × 作業時間 × 人件費単価', 'バッチ連動', 1, null, 0, '円/年', 'patrol_membrane', 1, null, false, 'H', '仮置き', 'ダイキアクシス', '交換回数 = 1 ÷ 膜交換年数。膜の部品代は「UF/MF膜モジュール（交換品）」に別計上。', 'amd_internal', 1220, null, null);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application) values ('ci2_dye_disposal', 'cm_p21_260820', '共通', 'OPEX', '使用済み菌体の処分', '使用済み菌体の処分', '脱水汚泥として産業廃棄物処分', '毎kg菌体比例', 1, null, 0, '円/kg-DCW', 'spent_disposal', 1, null, false, 'H', '推定', 'ダイキアクシス', '色素分解では酸で溶かさないため、菌体をそのまま汚泥として処分する想定。単価 = 脱水後の湿重量倍率 × 汚泥の処分単価。菌体使用回数が増えるほど処分量は減る。', 'amd_internal', 1300, null, 'dye');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application) values ('ci2_dye_analysis', 'cm_p21_260820', '共通', 'OPEX', '処理水の分析', '処理水の色・COD分析', '色度・吸光度・COD', '毎m³比例', 1, null, 4, '円/m³', null, 1, null, false, 'H', '仮置き', 'AMD（内部）', '金属回収の「回収物分析」と同水準で仮置き。', 'amd_internal', 1310, null, 'dye');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application) values ('ci2_dye_wash', 'cm_p21_260820', '共通', 'OPEX', '使用済み菌体の処分', '再利用前の洗浄（色素を外す工程）', '工程未確定', '毎m³比例', 1, null, 0, '円/m³', null, 1, null, false, 'H', '要検証', '中島先生', '菌体を繰り返し使うなら、色素を外す／洗い戻す工程が要る可能性がある。工程が決まっていないため0円で置き、中島先生へ確認中（酸処理が要るかの確認事項と同じ）。', 'amd_internal', 1320, null, 'dye');
update project_cost_questions set addressee = 'ダイキアクシス', question = '自動制御で無人運転する前提に置いていますが、実務上どこに人が必要になりますか。菌体の搬入、使用済み菌体の搬出、モジュール／膜の交換は、年何回・誰が・何時間で回る想定になりますか。', why_it_matters = '現行モデルは人件費を総コストへ算入していない（参考値でA:230円/m³、B:300円/m³）。B:投入／既設は総コスト349.7円/m³で+30%だが、人件費を戻すと-150円/m³で赤字に反転する。顧客側が0人になるならその作業はSXの巡回サービス原価へ移るはずで、現行モデルには1円も入っていない。 二段階版では人件費を手動運用の作業時間で総コストへ入れている（人件費を除いた値も併記）。無人運転の作業時間が分かれば置き換える。', impact_low = 0, impact_high = 300, status = 'open', answer = null, answered_on = null, linked_assumption_id = null, visibility = 'amd_internal', sort_order = 60, updated_at = now() where cost_question_id = 'cq_260820_06';
update project_cost_questions set addressee = 'AMD（内部）', question = '対象物質の濃度と取り込み効率を、色素の単位へ差し替える。現在は金属濃度50ppm ÷ 取り込み効率α 0.05 g金属/g菌体 で必要菌体量が回っている。', why_it_matters = '260820スプレッドシートには「色素」「脱色」「染料」の語が1つも無く、必要菌体量が金属の式のまま。設備構成は両ケース共通なので明細は使えるが、菌体量の駆動部だけが金属のまま残っている。ケースを取り違えたまま議論すると全部の数字の信頼が落ちる。', impact_low = null, impact_high = null, status = 'answered', answer = '二段階版で、対象物質の濃度・取り込み効率・菌体使用回数を色素分解と金属回収の別行に分けた。色素の値は文献相場による仮置きで、実測待ち。', answered_on = '2026-09-13', linked_assumption_id = 'ca_uptake_alpha', visibility = 'amd_internal', sort_order = 90, updated_at = now() where cost_question_id = 'cq_260820_09';
update project_cost_questions set addressee = 'AMD（内部）', question = '菌体使用回数を上げたときに、中央培養CAPEX（34.4円/m³）と現場側物流（11円/m³）が固定のままでよいか整理する。', why_it_matters = '菌体量が1/30になれば培養設備は小さくてよく、運ぶ回数も減るはずだが、現行モデルでは両方とも菌体使用回数に連動していない。使用回数を上げた瞬間、この2つが中央培養コストのほぼ全部になる。', impact_low = 0, impact_high = 45, status = 'answered', answer = '二段階版で菌体の原価を1kgあたりに換算したので、菌体使用回数を上げると培養設備の償却分も含めて回数分下がるようになった。代わりに「中央培養拠点の年間生産能力」を仮置きしており、実測待ち。現場側物流の搬送費は巡回サービスへ統合した。', answered_on = '2026-09-13', linked_assumption_id = null, visibility = 'amd_internal', sort_order = 110, updated_at = now() where cost_question_id = 'cq_260820_11';
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cq2_01', 'cm_p21_260820', '中島先生', '強化株を使う場合の閉鎖系の追加設備はいくらくらいになりそうですか。①培養槽と現場槽の排気の除菌フィルター ②培養廃液の不活化設備（オートクレーブか薬剤槽か） ③密閉性能検査を業者に頼む費用と頻度 ④作業区域の区画と保管設備。', '強化株の閉鎖系費用は全て仮置き（カテゴリー1相当）。第1段の菌体原価と、現場の総コストの両方に乗る。GILSPと判定されれば一部が不要になる。', 0, 52, 'open', null, null, null, 'amd_internal', 170);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cq2_02', 'cm_p21_260820', 'ダイキアクシス', '色素を処理した後の使用済み菌体は、脱水するとどれくらいの含水率になりますか。産業廃棄物（汚泥）として処分する場合の単価と、色素を含む菌体の廃棄物区分を教えてください。', '色素分解の後処理は「脱水後の湿重量 × 処分単価」で積んでいる。菌体を使い捨てにすると処分量が多く、総コストへの影響が大きい。', 0, 194, 'open', null, null, null, 'amd_internal', 180);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cq2_03', 'cm_p21_260820', 'AMD（内部）', 'SXが狙う色素系排液（染色・食品）の色の濃さを実測する。染色排水なら色素濃度（mg/L）、食品系なら色度とCODで取る。', '色素分解の必要菌体量は対象物質の濃度に比例する。いまは染色排水の文献相場（10〜250mg/L）の中央50mg/Lで仮置きしている。', null, null, 'open', null, null, null, 'amd_internal', 190);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cq2_04', 'cm_p21_260820', '杉浦先生', '自然株と強化株で、同じ菌体量・同じ条件のときの金属取り込み量を比べたデータはありますか。9/2の試験で、野生型が40ppmを取り込んだときの乾燥菌体量はいくらでしたか。', '金属回収の取り込み効率は、自然株を「強化株の5.3% × 40/50」と推定で置いている。株の切り替えで金属回収の総コストがどれだけ動くかは、この数字で決まる。', null, null, 'open', null, null, null, 'amd_internal', 200);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cq2_05', 'cm_p21_260820', '中島先生', '金属回収で使用済み菌体を酸で溶かす工程について教えてください。①乾燥菌体1kgを溶かすのに酸は何kg要りますか ②中和剤は何kg要りますか ③溶かした後の廃液は何L出ますか ④残渣は何kg残りますか。', '金属回収の後処理は260820版の値を換算したもので、酸・中和剤・廃液の量の根拠がない。色素側の処分費と同じ精度で比べるために、量だけをもらってAMD側で円へ変換する。', null, null, 'open', null, null, null, 'amd_internal', 210);
update project_cost_notes set section = 'benchmark', title = '人件費を総コストから外した判断の裏付け', body_md = '中島先生の当初設計は人員が張り付く前提だった。それではコスト的に成立せず、そもそも静脈側（排水処理）に人を張り付ける装置は売れないという判断で、ほぼ人件費のかからない想定へ切り替えた（まさ判断）。

同じツムラヒアリングに、この判断を支える一次情報がある。

- 排水処理・ユーティリティ管理は**有資格者が必要**で、50〜60代のベテランが数年以内に退職する懸念
- 担当者が2名で空き人材がいない場合、**1名の退職だけで工場運転不能になるリスク**
- 育成・採用が追いつかず、**運転管理のアウトソース化を含む対策を模索中**。外部委託サービスへの問い合わせが増加

つまり「人を減らせる」はこの市場ではむしろ売り文句になる。ただし**顧客側の人が0人になるなら、菌体の搬入・使用済み菌体の搬出・モジュール／膜の交換は誰かがやることになり、SX側の巡回サービス原価として立て直す必要がある（現行モデルには未計上）**。

**2026-09-13 追記**: 二段階版では人件費を総コストへ入れ、人件費を除いた値を併記する形に変えた（まさ指示）。無人運転を狙う判断は変えていないが、作業時間が確認できるまでは手動運用の値で積む。', source_url = null, source_label = '2026-07 ツムラ ヒアリングメモ / 2026-08-23 まさ判断', visibility = 'amd_internal', sort_order = 30, updated_at = now() where cost_note_id = 'cn_260820_b3';
update project_cost_notes set section = 'caveat', title = '菌体の製造原価は、生産能力いっぱいで割っている', body_md = '二段階版では、乾燥菌体1kgの原価を「(培養設備の償却年額 ＋ 年ごとの固定費) ÷ 年間生産能力 ＋ 菌体量に比例する費用」で出す。

**年間生産能力いっぱいに稼働している前提**なので、実際の供給量が能力を下回ると、1kgあたりの原価は上がる。旧版の「供給先数で割る」はこの考え方に置き換えたため使っていない。

年間生産能力（33,333kg/年）は、旧版が暗黙に置いていた「必要な菌体量＝生産量」を引き継いだ仮置き。培養液1Lあたりの1日の増殖量と培養容積が分かるまで確定しない。', source_url = null, source_label = '原典③シート I35', visibility = 'amd_internal', sort_order = 40, updated_at = now() where cost_note_id = 'cn_260820_c4';
update project_cost_notes set section = 'history', title = 'この試算が答えていないこと', body_md = '- **回収物の売却収入がモデルに1円も入っていない。** 収入は処理費500円/m³のみ。レアアース回収などのアップサイドが数字として表現できていない
- **事業規模との接続がない。** 1拠点あたり年商1,500万円（30,000m³ × 500円）。FY35 売上200億円という目標に対して、何拠点必要かが出ていない
- **酸処理（菌体再生）の設備が未計上。** 金属回収で菌体を再生して使う経路を採るなら設備が要るが、金額が入っていない
- **閉鎖系の追加費用と巡回サービスは仮置き。** 金額の根拠となる見積がまだない（二段階版で追加）
- **色素側の数字は実測がない。** 色素の濃さ・取り込み効率・菌体使用回数・使用済み菌体の含水率は文献相場か仮置き', source_url = null, source_label = '2026-08-23 レビュー', visibility = 'amd_internal', sort_order = 20, updated_at = now() where cost_note_id = 'cn_260820_h2';
update project_cost_notes set section = 'reading_guide', title = '各行が何を見るためのものか', body_md = '- **第1段 菌体の製造原価** — 株ごとに、乾燥菌体1kgをつくる原価。培養設備の償却・年ごとの固定費・菌体量に比例する費用に分けて見る
- **第2段 菌体費** — 第1段の原価 × 排水1m³あたりに使い切る菌体量
- **現場設備 OPEX／CAPEX** — 方式ごとのコア工程（循環＝カートリッジ、投入＝UF/MF）と、槽
- **人件費** — 現場の運転。総コストに含み、除いた値も併記する
- **巡回サービス** — 菌体の搬入・搬出、モジュールと膜の交換作業
- **閉鎖系の追加** — 強化株のときだけ乗る費用。第1段の分と現場の分の合計
- **後処理** — 使用済み菌体の後始末。金属回収は酸処理、色素分解は汚泥としての処分
- **事業全体 総コスト** — 売価500円/m³に対して成立するか', source_url = null, source_label = '原典②シート「見る意味」列', visibility = 'amd_internal', sort_order = 10, updated_at = now() where cost_note_id = 'cn_260820_r1';
update project_cost_notes set section = 'reading_guide', title = '色素分解は、菌体使用回数で総コストが大きく動く', body_md = '色素分解の菌体使用回数だけを動かしたときの総コスト（円/m³）。他の前提は据え置き。

| 株 | 菌体使用回数 | 色素分解 B:投入／既設 | 人件費を除くと |
|---|---|---|---|
| 強化株 | 1回 | 878.0 | 578.0 |
| 強化株 | 10回 | 540.0 | 240.0 |
| 強化株 | 30回 | 504.9 | 204.9 |
| 自然株 | 1回 | 826.5 | 526.5 |
| 自然株 | 10回 | 517.2 | 217.2 |
| 自然株 | 30回 | 484.2 | 184.2 |

旧版では中央培養の設備償却が使用回数に連動しない固定額だったため、10回を超えると頭打ちになっていた。二段階版では菌体原価を1kgあたりで持つので、**菌体費と使用済み菌体の処分費がどちらも使用回数に反比例する**。

杉浦先生へは引き続き「10回を超えるか」を確認する。', source_url = null, source_label = '2026-09-13 感度分析（二段階版の計算エンジンで実測）', visibility = 'amd_internal', sort_order = 30, updated_at = now() where cost_note_id = 'cn_260820_r3';
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cn2_c7', 'cm_p21_260820', 'caveat', '強化株の閉鎖系費用は、カテゴリー1相当で積んでいる', '強化株の閉鎖系費用は、判定が確定していないため**カテゴリー1相当**で積んでいる。

**GILSP**と判定されれば、排気の除菌フィルター（設備と交換）、培養設備と現場設備の密閉性能検査、処理水の不活化は、法令上は求められない可能性がある。作業区域の区画・表示、区別保管、廃液の扱い、教育訓練は、GILSPでも必要。

この切り分けで外れる可能性がある額は、B:投入／既設で色素分解 約31.0円/m³、金属回収 約30.3円/m³。', null, '産業利用二種省令 別表・経済産業省／NITE「第二種使用等の手引き」第5.1版（令和8年9月）', 'amd_internal', 70);
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cn2_c8', 'cm_p21_260820', 'caveat', '人件費は手動運用の作業時間で入れている', '中島先生の試算にある1バッチあたり作業時間（A:循環5.75時間、B:投入7.5時間）で、人件費を総コストへ入れている。

自動制御で無人運転する設計方針は変えていない。無人運転で何時間まで減るかが分かっていないため、いまは根拠のある手動運用の値を使い、**人件費を除いた値も併記**している。実態はこの2つの間にある。', null, null, 'amd_internal', 80);
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cn2_c9', 'cm_p21_260820', 'caveat', '色素分解の数字は、文献相場と仮置きで組んでいる', '色素分解ケースの対象物質の濃度（50mg/L）、取り込み効率（0.05g/g）、菌体使用回数（1回）、脱水後の湿重量倍率（5倍）は、いずれも実測ではない。

特に**菌体使用回数**は総コストへの効き方が大きい。二段階版では菌体費と処分費がどちらも使用回数に反比例するため、1回と10回で総コストが大きく変わる。', null, null, 'amd_internal', 90);
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cn2_c10', 'cm_p21_260820', 'caveat', '後処理の数字は、金属と色素で根拠の置き方が違う', '金属回収の後処理（酸・洗浄水・中和剤・残渣処分・廃液処理で乾燥菌体1kgあたり約39円）は、260820版の値を換算したもので、酸や廃液の量の根拠は確認できていない。

色素分解の後処理（使用済み菌体を汚泥として処分。乾燥菌体1kgあたり約175円）は、脱水後の湿重量と汚泥の処分相場から積んだ。

**同じ精度で比べられていない。** 菌体を使い捨てにしたとき色素分解が金属回収より高く見えるのは、この差による部分がある。金属側は酸で菌体を溶かした後の廃液量によっては上がる可能性が高い。', null, null, 'amd_internal', 100);
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cn2_h3', 'cm_p21_260820', 'history', '260913 二段階版への組み替え', '2026-09-13、まさの指摘で計算の組み方を二段階に変えた。

**なぜ変えたか**: 旧版は中央培養の費用を「排水1m³あたり」で持ち、設備償却を必要菌体量に連動しない固定額で置いていた。そのため菌体使用回数を変えると、菌体1kgあたりの原価が見かけ上 98円 → 約440円 → 約1,200円と動いてしまい、「製造原価は株で決まり、用途では変わらない」という事実と合っていなかった。

**何を変えたか**
- 中央培養の明細を 円/m³ から 円/kg-DCW と年額固定費へ換算し、年間生産能力で割って菌体1kgの原価を出す形にした
- 前提と明細に「どの株・どの用途に効くか」を持たせ、画面で強化株／自然株を切り替えられるようにした
- 色素分解と金属回収を別行に分け、横に並べて比較できるようにした
- 人件費を総コストへ入れた（除いた値も併記）
- 巡回サービス、閉鎖系の追加費用（強化株のみ）、色素用の後処理、色素の濃さを追加した
- 金属の取り込み効率を、9/2定例の試験結果から株ごとに置き直した（自然株 約4.2%、強化株 5.3%以上）

**旧版との対応**（自然株・金属回収・B:投入／既設）: 旧版 349.7円/m³ から、搬送費を巡回サービスへ統合 -9.0、金属の取り込み効率を0.05→0.042へ置き直し +33.0、巡回サービスを追加 +34.4、人件費を算入 +300.0 で、708.1円/m³。旧版と同じ条件に戻すと4シナリオとも旧版の数字に一致することを、計算エンジンの点検で確認している。

**二段階版の B:投入／既設**: 強化株で色素分解 878.0円/m³、金属回収 715.0円/m³。自然株で色素分解 826.5円/m³、金属回収 708.1円/m³。いずれも人件費を手動運用の時間で含む。', null, null, 'amd_internal', 30);
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cn2_r5', 'cm_p21_260820', 'reading_guide', '二段階の読み方', '1. **株を選ぶ** — 画面上部のスイッチで強化株か自然株を選ぶ。保存はされない
2. **第1段で菌体1kgの原価を見る** — 同じ株なら、色素分解でも金属回収でも同じ原価を使う
3. **第2段で用途を並べて見る** — 色素分解と金属回収で違うのは、排水1m³に使い切る菌体の量と、後処理だけ
4. **下の詳細は用途のタブで切り替える** — 成立ライン・内訳・確からしさは、選んだ用途の4シナリオで出す', null, null, 'amd_internal', 5);
commit;
